  // The server supplies the remaining time, so the projector's clock need
  // not match the host. Recompute from a deadline rather than counting ticks.
  let countdownTick;
  function startCountdown() {
    clearTimeout(countdownTick);
    const clock = root.querySelector('[data-remaining-ms]');
    if (!clock) return;
    const end = performance.now() + Number(clock.dataset.remainingMs);
    function tick() {
      const remaining = Math.max(0, end - performance.now());
      const seconds = Math.ceil(remaining / 1000);
      clock.textContent = `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
      if (seconds) countdownTick = setTimeout(tick, remaining - (seconds - 1) * 1000);
      else refresh();
    }
    tick();
  }

